// ── Types ─────────────────────────────────────────────────────────────────────
type RiskCategory = "Technical" | "Operational" | "Compliance" | "Strategic" | "Third-Party" | "Physical" | "Human";
type RiskStatus = "open" | "mitigating" | "treated" | "accepted" | "closed";
type RiskTreatment = "mitigate" | "accept" | "transfer" | "avoid";
type Likelihood = 1 | 2 | 3 | 4 | 5;
type Impact = 1 | 2 | 3 | 4 | 5;

interface Risk {
  id: string;
  title: string;
  description: string;
  category: RiskCategory;
  status: RiskStatus;
  treatment: RiskTreatment;
  likelihood: Likelihood;
  impact: Impact;
  inherentScore: number;
  residualScore: number;
  owner: string;
  reviewer: string;
  dateIdentified: string;
  nextReviewDate: string;
  mitigationActions: string[];
  relatedControls: string[];
  affectedAssets: string[];
  notes: string;
}

// ── Constants ─────────────────────────────────────────────────────────────────
const CATEGORIES: RiskCategory[] = ["Technical", "Operational", "Compliance", "Strategic", "Third-Party", "Physical", "Human"];
const STATUSES: RiskStatus[] = ["open", "mitigating", "treated", "accepted", "closed"];
const TREATMENTS: RiskTreatment[] = ["mitigate", "accept", "transfer", "avoid"];
const LIKELIHOOD_LABELS: Record<number, string> = { 1: "Rare", 2: "Unlikely", 3: "Possible", 4: "Likely", 5: "Almost Certain" };
const IMPACT_LABELS: Record<number, string> = { 1: "Insignificant", 2: "Minor", 3: "Moderate", 4: "Major", 5: "Catastrophic" };
