// ── Score color helpers ───────────────────────────────────────────────────────
function scoreClass(score: number): string {
  if (score >= 15) return "text-red-400";
  if (score >= 10) return "text-orange-400";
  if (score >= 5) return "text-yellow-400";
  return "text-green-400";
}

function scoreBg(score: number): string {
  if (score >= 15) return "bg-red-500/15 border-red-500/40 text-red-400";
  if (score >= 10) return "bg-orange-400/15 border-orange-400/40 text-orange-400";
  if (score >= 5) return "bg-yellow-400/15 border-yellow-400/40 text-yellow-400";
  return "bg-green-500/15 border-green-500/40 text-green-400";
}

function cellColor(score: number): string {
  if (score >= 15) return "bg-red-500/30 border-red-500/50 hover:bg-red-500/50";
  if (score >= 10) return "bg-orange-400/25 border-orange-400/40 hover:bg-orange-400/40";
  if (score >= 5) return "bg-yellow-400/20 border-yellow-400/35 hover:bg-yellow-400/35";
  return "bg-green-500/15 border-green-500/30 hover:bg-green-500/25";
}

