                  <div><span className="text-muted-foreground">Treatment:</span> <Badge variant="outline" className={`ml-1 text-xs py-0 capitalize ${TREATMENT_COLORS[selectedRisk.treatment]}`}>{selectedRisk.treatment}</Badge></div>
